import React, { useState } from 'react';

const Home = () => {
  // Liste de cours simple (facile à modifier en direct devant le prof)
  const [courses, setCourses] = useState([
    { id: 1, title: "Hacking Éthique & Pentest : Les Fondations", level: "Débutant", price: 25000, isFree: false },
    { id: 2, title: "Sécurisation des Architectures Réseaux & pfSense", level: "Avancé", price: 40000, isFree: false },
    { id: 3, title: "Introduction à la Cybersécurité et Hygiène Numérique", level: "Débutant", price: 0, isFree: true }
  ]);

  // États pour la recherche agrandie et le paiement simulé
  const [searchQuery, setSearchQuery] = useState('');
  const [showSearchInput, setShowSearchInput] = useState(false);
  const [selectedCourse, setSelectedCourse] = useState(null);
  const [paymentMethod, setPaymentMethod] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [paymentSuccess, setPaymentSuccess] = useState(false);

  const déclencherPaiementSimulé = (e) => {
    e.preventDefault();
    setIsProcessing(true);
    setTimeout(() => {
      setIsProcessing(false);
      setPaymentSuccess(true);
    }, 3000);
  };

  return (
    <div className="min-h-screen bg-[#030712] text-gray-100 font-sans selection:bg-blue-500/30">
      
      {/* 1. BARRE DE NAVIGATION */}
      <header className="border-b border-slate-800 bg-gray-950/50 backdrop-blur-md px-8 py-5 flex justify-between items-center sticky top-0 z-40">
        <div className="flex items-center gap-2">
          <div className="bg-blue-600 text-white font-black px-3 py-1.5 rounded text-md tracking-tighter">A</div>
          <span className="text-lg font-bold tracking-wider text-white">AVALON <span className="text-blue-500">SECURE</span></span>
        </div>

        {/* Partie Droite : Recherche optimisée + Actions */}
        <div className="flex items-center gap-6 ml-auto">
          
          {/* ZONE DE RECHERCHE AGRANDIE ET PLUS VISIBLE */}
          <div className="flex items-center gap-3 bg-slate-900/90 rounded-full p-2 border border-slate-700 shadow-inner transition-all duration-300">
            {showSearchInput && (
              <input
                type="text"
                placeholder="Rechercher un cours..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="bg-transparent border-none text-sm text-gray-200 focus:outline-none pl-4 w-48 transition-all duration-300"
              />
            )}
            <button 
              onClick={() => setShowSearchInput(!showSearchInput)}
              className="w-9 h-9 rounded-full bg-slate-800 hover:bg-blue-600 flex items-center justify-center text-gray-300 hover:text-white transition-colors duration-200 text-base shadow-md"
              title="Rechercher un cours"
            >
              🔍
            </button>
          </div>

          <a href="/login" className="text-gray-400 hover:text-white text-sm font-semibold transition">
            Connexion
          </a>
          
          <a href="/register" className="bg-blue-600 text-white px-5 py-2.5 rounded-lg text-sm font-bold hover:bg-blue-500 transition shadow-lg shadow-blue-600/20">
            Rejoindre l'Académie
          </a>
        </div>
      </header>

      {/* 2. SECTION HÉRO CENTRALE */}
      <section className="relative overflow-hidden pt-24 pb-20 px-4">
        {/* Halo lumineux de fond */}
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[300px] bg-blue-500/10 blur-[130px] rounded-full pointer-events-none"></div>

        <div className="max-w-4xl mx-auto text-center relative z-10">
          
          {/* Badge International */}
          <div className="inline-flex items-center gap-2 bg-blue-950/40 border border-blue-500/30 px-4 py-1.5 rounded-full mb-6">
            <span className="w-1.5 h-1.5 bg-blue-400 rounded-full animate-pulse"></span>
            <span className="text-[11px] font-semibold text-blue-300 tracking-wider uppercase">Écosystème Académique International</span>
          </div>

          {/* Grand Titre principal */}
          <h2 className="text-4xl md:text-5xl font-black tracking-tight text-white mb-6 leading-tight">
            Déployez vos compétences <br />
            d'élite avec <br />
            <span className="text-blue-500 drop-shadow-[0_0_35px_rgba(59,130,246,0.3)]">AVALON SECURE ACADEMY</span>
          </h2>

          {/* Textes descriptifs */}
          <p className="text-gray-400 max-w-2xl mx-auto text-sm md:text-base leading-relaxed mb-10">
            Accédez à un contenu d'ingénierie réseau et de cyberdéfense de classe mondiale. <br />
            Validez nos parcours fondamentaux gratuits et accédez aux modules avancés de niveau expert.
          </p>

          {/* Boutons de redirection vers l'inscription */}
          <div className="flex flex-col items-center gap-4">
            <a href="/register" className="bg-blue-500 text-gray-950 font-black px-10 py-4 rounded-lg text-sm hover:bg-blue-400 transition shadow-lg shadow-blue-500/20 uppercase tracking-wider">
              S'inscrire maintenant
            </a>
          </div>

        </div>
      </section>

      {/* 3. SECTION DES COURS */}
      <section id="courses" className="max-w-6xl mx-auto px-4 py-12 border-t border-slate-900">
        <h3 className="text-sm font-bold mb-8 text-slate-500 tracking-widest uppercase text-center md:text-left">
          Formations disponibles
        </h3>
        
        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
          {courses
            .filter(c => c.title.toLowerCase().includes(searchQuery.toLowerCase()))
            .map((course) => (
              <div key={course.id} className="bg-gray-900/60 border border-slate-800 rounded-xl p-5 flex flex-col justify-between hover:border-slate-700 transition">
                <div>
                  <div className="flex justify-between items-center mb-4">
                    <span className="bg-slate-800 text-blue-400 text-xs px-2.5 py-1 rounded-full font-semibold">
                      {course.level}
                    </span>
                    {course.isFree && (
                      <span className="bg-blue-500/10 text-blue-400 text-xs px-2.5 py-1 rounded-full font-bold border border-blue-500/20">
                        Gratuit
                      </span>
                    )}
                  </div>
                  <h4 className="text-base font-bold mb-4 text-white">{course.title}</h4>
                </div>
                
                <div>
                  <p className="text-lg font-black text-blue-500 mb-4">
                    {course.isFree ? "0 FCFA" : `${course.price.toLocaleString()} FCFA`}
                  </p>
                  
                  {course.isFree ? (
                    <button
                      onClick={() => alert('Accès débloqué pour ce cours gratuit !')}
                      className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-2.5 rounded-lg text-xs transition"
                    >
                      Suivre gratuitement
                    </button>
                  ) : (
                    <button
                      onClick={() => {
                        setSelectedCourse(course);
                        setPaymentMethod('');
                        setPaymentSuccess(false);
                      }}
                      className="w-full bg-slate-950 hover:bg-slate-800 text-gray-300 border border-slate-800 font-bold py-2.5 rounded-lg text-xs transition"
                    >
                      Acheter le cours
                    </button>
                  )}
                </div>
              </div>
            ))}
        </div>
      </section>

      {/* MODAL DE PAIEMENT SIMULÉ (SANDBOX) */}
      {selectedCourse && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4 z-50">
          <div className="w-full max-w-md bg-gray-900 border border-slate-800 rounded-xl p-6 relative">
            <button onClick={() => setSelectedCourse(null)} className="absolute top-4 right-4 text-gray-400 hover:text-white">✕</button>

            {!paymentSuccess ? (
              <>
                <h3 className="text-lg font-bold mb-1">Finaliser votre achat</h3>
                <p className="text-xs text-gray-400 mb-4">{selectedCourse.title}</p>
                
                <div className="bg-gray-950 p-3 rounded-lg border border-slate-800 flex justify-between items-center mb-6">
                  <span className="text-xs text-gray-400">Prix unique :</span>
                  <span className="text-lg font-bold text-blue-500">{selectedCourse.price.toLocaleString()} FCFA</span>
                </div>

                <form onSubmit={déclencherPaiementSimulé} className="space-y-6">
                  <div className="grid grid-cols-2 gap-3">
                    {['mtn', 'wave', 'card', 'paypal'].map((method) => (
                      <button
                        key={method}
                        type="button"
                        onClick={() => setPaymentMethod(method)}
                        className={`p-3 rounded-lg border text-xs font-bold uppercase tracking-wider transition ${paymentMethod === method ? 'border-blue-500 bg-blue-500/10 text-blue-400' : 'border-slate-800 bg-gray-950'}`}
                      >
                        {method === 'mtn' ? 'MTN MoMo' : method === 'wave' ? 'Wave' : method === 'card' ? 'Carte' : 'PayPal'}
                      </button>
                    ))}
                  </div>

                  {isProcessing ? (
                    <div className="w-full text-center py-3 bg-gray-950 border border-slate-800 rounded-lg text-xs text-gray-400">
                      Connexion sécurisée en cours...
                    </div>
                  ) : (
                    <button
                      type="submit"
                      disabled={!paymentMethod}
                      className={`w-full py-3 rounded-lg font-bold text-xs transition ${paymentMethod ? 'bg-blue-600 text-white' : 'bg-gray-800 text-gray-500 cursor-not-allowed'}`}
                    >
                      Simuler le paiement
                    </button>
                  )}
                </form>
              </>
            ) : (
              <div className="text-center py-6">
                <div className="text-blue-500 text-4xl mb-3">🎉</div>
                <h3 className="text-xl font-bold mb-2">Paiement validé !</h3>
                <p className="text-gray-400 text-xs mb-6">Le cours a été ajouté à votre espace.</p>
                <button onClick={() => setSelectedCourse(null)} className="w-full bg-blue-600 text-white font-bold py-2 rounded-lg text-xs">
                  Ouvrir la formation
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default Home;
